:root {
  /* Navy Blue & Sage Green Palette */
  --color-navy: #162d50;
  --color-navy-dark: #0f203b;
  --color-navy-soft: #e8eef6;

  --color-sage: #5f8567;
  --color-sage-dark: #486950;
  --color-sage-light: #e7f0e9;
  --color-sage-tint: #f4f8f5;

  --color-bg: var(--color-sage-tint);
  --color-surface: #ffffff;
  --color-text: #152238;
  --color-text-muted: #526277;
  --color-border: #cedbd1;

  --font-sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto,
    "Helvetica Neue", Arial, sans-serif;

  --container-max: 1160px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --shadow-sm: 0 2px 8px rgba(22, 45, 80, 0.06);
  --shadow-md: 0 8px 24px rgba(22, 45, 80, 0.09);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--color-navy);
  text-decoration: none;
}

a:hover {
  color: var(--color-sage-dark);
}

button,
input {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--color-sage);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  background: var(--color-navy);
  color: #ffffff;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 1000;
  font-weight: 600;
}

.skip-link:focus {
  top: 0.75rem;
  color: #ffffff;
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* ==========================================================================
   Header / Navbar (Logo Left | Links Center | Phone No. Right)
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--color-surface);
  border-bottom: 2px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.nav-wrapper {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  min-height: 76px;
  gap: 1.25rem;
}

.brand {
