  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 600;
  transition: background-color 0.16s ease;
}

.btn-primary:hover {
  background: var(--color-sage-dark);
  color: #ffffff;
}

.btn-secondary {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  padding: 0.58rem 0.85rem;
  border-radius: var(--radius-sm);
  background: var(--color-sage-light);
  border: 1px solid var(--color-border);
  color: var(--color-navy);
  font-size: 0.86rem;
  font-weight: 600;
  transition: background-color 0.16s ease, border-color 0.16s ease;
}

.btn-secondary:hover {
  background: var(--color-sage);
  border-color: var(--color-sage);
  color: #ffffff;
}

.empty-state {
  background: var(--color-surface);
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 1.5rem;
  text-align: center;
  color: var(--color-text-muted);
}

.empty-state h3 {
  margin: 0 0 0.45rem;
  color: var(--color-navy);
}

.empty-state p {
  margin: 0 0 1.15rem;
}

/* ==========================================================================
   Footer (Logo/Name Left | 3 Lines Middle | 3 Lines Right)
   ========================================================================== */
.site-footer {
  background: var(--color-navy-dark);
  color: #dbe4ef;
  padding: 2.5rem 0 1.25rem;
  margin-top: 1rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  color: #ffffff;
  font-weight: 700;
  font-size: 1.15rem;
  margin-bottom: 0.65rem;
}

.footer-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
  font-size: 0.92rem;
}

.footer-lines a {
  color: #c5d7cb;
}

.footer-lines a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.footer-heading {
  margin: 0 0 0.75rem;
  color: #9ec5a6;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-bottom {
  padding-top: 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.84rem;
  color: #a9b9cd;
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */
@media (max-width: 960px) {
  .hero__grid {
    grid-template-columns: 1fr;
  }

  .gallery-grid,
  .doctors-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .filter-split {
    grid-template-columns: 1fr;
  }

  .chart-bars {
    grid-template-columns: repeat(3, 1fr);
    row-gap: 1.5rem;
  }
}

@media (max-width: 760px) {
  .nav-wrapper {
    grid-template-columns: 1fr auto;
  }

  .nav-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
  }

  .nav-phone {
    display: none;
  }

  .nav-center {
    grid-column: 1 / -1;
    justify-content: stretch;
  }

  .nav-menu {
    display: none;
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
    padding: 0.5rem 0 0.85rem;
    border-top: 1px solid var(--color-border);
  }

  .nav-menu.is-open {
    display: flex;
  }

  .gallery-grid,
  .doctors-grid,
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .filter-panel {
    padding: 1.15rem;
  }

  .chart-bars {
    grid-template-columns: repeat(2, 1fr);
  }
}

