/* ==========================================================================
   DocEase Clinic - Services & Specialties Page
   Matches DocEase Sage Green, Navy Blue & White Theme + Prototype Layout
   ========================================================================== */

:root {
  /* Navy Blue & Sage Green Palette (shared with DocEase homepage) */
  --color-navy: #162d50;
  --color-navy-dark: #0f203b;
  --color-navy-soft: #e8eef6;

  --color-sage: #5f8567;
  --color-sage-dark: #486950;
  --color-sage-light: #e7f0e9;
  --color-sage-tint: #f4f8f5;

  --color-bg: var(--color-sage-tint);
  --color-surface: #ffffff;
  --color-text: #152238;
  --color-text-muted: #526277;
  --color-border: #cedbd1;

  --font-sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto,
    "Helvetica Neue", Arial, sans-serif;

  --container-max: 1160px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --shadow-sm: 0 2px 8px rgba(22, 45, 80, 0.06);
  --shadow-md: 0 8px 24px rgba(22, 45, 80, 0.09);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--color-navy);
  text-decoration: none;
}

a:hover {
  color: var(--color-sage-dark);
}

button {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--color-sage);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  background: var(--color-navy);
  color: #ffffff;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 1000;
  font-weight: 600;
}

.skip-link:focus {
  top: 0.75rem;
  color: #ffffff;
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* ==========================================================================
   Shared Header / Navbar
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--color-surface);
  border-bottom: 2px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.nav-wrapper {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  min-height: 76px;
  gap: 1.25rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--color-navy);
}

.brand__logo {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  border: 1px solid var(--color-border);
  flex-shrink: 0;
}

.brand__sub {
  display: block;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--color-sage-dark);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.nav-center {
  display: flex;
  justify-content: center;
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  display: inline-block;
  padding: 0.45rem 0.25rem;
  font-weight: 600;
  font-size: 0.98rem;
  color: var(--color-text);
  border-bottom: 2px solid transparent;
  transition: color 0.18s ease, border-color 0.18s ease;
  white-space: nowrap;
}

.nav-link:hover {
  color: var(--color-navy);
  border-bottom-color: var(--color-sage);
}

.nav-link.is-active {
  color: var(--color-navy);
  border-bottom-color: var(--color-navy);
}

.nav-phone {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.52rem 1rem;
  border-radius: var(--radius-pill);
  background: var(--color-navy);
  color: #ffffff;
  font-weight: 600;
  font-size: 0.9rem;
  white-space: nowrap;
  transition: background-color 0.18s ease;
}

.nav-phone:hover {
  background: var(--color-sage-dark);
  color: #ffffff;
}

.nav-toggle {
  display: none;
  background: var(--color-sage-light);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.45rem 0.7rem;
  cursor: pointer;
  color: var(--color-navy);
  font-weight: 600;
}

/* ==========================================================================
   Shared Eyebrow Label
   ========================================================================== */
.section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 0.75rem;
  padding: 0.32rem 0.85rem;
  border-radius: var(--radius-pill);
  background: var(--color-sage-light);
  border: 1px solid var(--color-border);
  color: var(--color-navy);
  font-size: 0.86rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.section-eyebrow__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-sage-dark);
  flex-shrink: 0;
}

/* ==========================================================================
   Section 1: Our Services (Left Intro + Right 3x2 Cards Grid)
   ========================================================================== */
.services-section {
  padding: 3rem 0 2.75rem;
  background: linear-gradient(
    135deg,
    var(--color-sage-light) 0%,
    var(--color-bg) 55%,
    var(--color-navy-soft) 100%
  );
  border-bottom: 1px solid var(--color-border);
}

.services-layout {
  display: grid;
  grid-template-columns: minmax(250px, 0.92fr) 2.08fr;
  gap: 2.25rem;
  align-items: start;
}

.services-intro {
  padding-top: 0.35rem;
}

.services-intro__title {
  margin: 0 0 1.6rem;
  font-size: clamp(1.85rem, 3.2vw, 2.45rem);
  line-height: 1.16;
  color: var(--color-navy);
  letter-spacing: -0.015em;
}

.services-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.72rem 1.35rem;
  border-radius: var(--radius-pill);
  background: var(--color-navy);
  border: 2px solid var(--color-navy);
  color: #ffffff;
  font-size: 0.94rem;
  font-weight: 600;
  box-shadow: var(--shadow-sm);
  transition: background-color 0.18s ease, border-color 0.18s ease,
    transform 0.16s ease;
}

.services-cta-btn:hover {
  background: var(--color-sage-dark);
  border-color: var(--color-sage-dark);
  color: #ffffff;
  transform: translateY(-1px);
}

.services-cta-btn__arrow {
  display: inline-block;
  transition: transform 0.18s ease;
}

.services-cta-btn:hover .services-cta-btn__arrow {
  transform: translateX(3px);
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
}

.service-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-top: 4px solid var(--color-navy);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.15rem 1rem;
  min-height: 158px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1rem;
  transition: transform 0.18s ease, box-shadow 0.18s ease,
    border-color 0.18s ease;
}

.service-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-sage);
  border-top-color: var(--color-sage-dark);
}

.service-card__title {
  margin: 0 0 0.45rem;
  font-size: 1.04rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-navy);
}

.service-card__desc {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: var(--color-text-muted);
}

.service-card__arrow {
  align-self: flex-end;
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1;
  color: var(--color-navy);
  transition: transform 0.18s ease, color 0.18s ease;
}

.service-card:hover .service-card__arrow {
  transform: translateX(4px);
  color: var(--color-sage-dark);
}

/* ==========================================================================
   Section 2: Clinic Image (Left) + Why Choose DocEase? (Right)
   ========================================================================== */
.why-section {
  padding: 3rem 0 3.25rem;
  background: var(--color-bg);
}

.why-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: center;
}

.clinic-photo-card {
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 0.85rem;
  box-shadow: var(--shadow-md);
}

.clinic-photo-card img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: var(--radius-md);
}

.why-content__title {
  margin: 0 0 0.85rem;
  font-size: clamp(1.65rem, 2.8vw, 2.2rem);
  line-height: 1.18;
  color: var(--color-navy);
  letter-spacing: -0.015em;
}

.why-content__desc {
  margin: 0 0 1.75rem;
  font-size: 1rem;
  line-height: 1.65;
  color: var(--color-text-muted);
  max-width: 540px;
}

.why-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.why-stat {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem 0.85rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.45rem;
}

.why-stat__icon {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--color-sage-light);
  border: 1.5px solid var(--color-sage);
  color: var(--color-navy);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.15rem;
}

.why-stat__value {
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.15;
  color: var(--color-navy);
}

.why-stat__label {
  font-size: 0.84rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--color-text-muted);
}

/* ==========================================================================
   Shared Navy-Blue Footer
   ========================================================================== */
.site-footer {
  background: var(--color-navy-dark);
  color: #dbe4ef;
  padding: 2.5rem 0 1.25rem;
  margin-top: 0.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  color: #ffffff;
  font-weight: 700;
  font-size: 1.15rem;
  margin-bottom: 0.65rem;
}

.footer-brand__logo {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  border: 1px solid rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
}

.footer-tagline {
  margin: 0;
  font-size: 0.9rem;
  max-width: 300px;
}

.footer-heading {
  margin: 0 0 0.75rem;
  color: #9ec5a6;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
  font-size: 0.92rem;
}

.footer-lines a {
  color: #c5d7cb;
}

.footer-lines a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.footer-bottom {
  padding-top: 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.84rem;
  color: #a9b9cd;
}

/* ==========================================================================
   Responsive Breakpoints (Tablet & Mobile Prototype)
   ========================================================================== */
@media (max-width: 960px) {
  .services-layout {
    grid-template-columns: 1fr;
    gap: 1.75rem;
  }

  .services-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .why-layout {
    grid-template-columns: 1fr;
    gap: 1.75rem;
  }
}

@media (max-width: 760px) {
  .nav-wrapper {
    grid-template-columns: 1fr auto;
  }

  .nav-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
  }

  .nav-phone {
    display: none;
  }

  .nav-center {
    grid-column: 1 / -1;
    justify-content: stretch;
  }

  .nav-menu {
    display: none;
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
    padding: 0.5rem 0 0.85rem;
    border-top: 1px solid var(--color-border);
  }

  .nav-menu.is-open {
    display: flex;
  }

  .services-section {
    padding: 2.15rem 0 2rem;
  }

  .why-section {
    padding: 2.15rem 0 2.5rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 540px) {
  .services-grid {
    grid-template-columns: 1fr;
  }

  .service-card {
    min-height: 124px;
  }

  .why-stats {
    grid-template-columns: 1fr;
  }

  .why-stat {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: auto auto;
    column-gap: 0.9rem;
    align-items: center;
  }

  .why-stat__icon {
    grid-row: 1 / 3;
    margin-bottom: 0;
  }
}

/* ==========================================================================
   DocEase Clinic - Services & Specialties Page Script
   ========================================================================== */

(function () {
  "use strict";

  function initNavigation() {
    const toggle = document.getElementById("navToggle");
    const menu = document.getElementById("navMenu");
    if (!toggle || !menu) return;

    function closeMenu() {
      menu.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
    }

    toggle.addEventListener("click", () => {
      const isOpen = menu.classList.toggle("is-open");
      toggle.setAttribute("aria-expanded", String(isOpen));
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && menu.classList.contains("is-open")) {
        closeMenu();
        toggle.focus();
      }
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    const yearEl = document.getElementById("currentYear");
    if (yearEl) {
      yearEl.textContent = String(new Date().getFullYear());
    }

    initNavigation();
  });
})();

